import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`prototype-builder`,heroTitle:`Build your prototype in minutes`,heroSubtitle:`Perplexity Computer turns a rough idea into screens, interaction notes, and a prototype brief your team can review immediately.`,inputUrlCta:`Build my prototype`,inputUrlPlaceholder:`e.g. notion.so/brief or docs.google.com/document/...`,inputUrlPrefill:`Go to {url} and turn it into a complete prototype brief. (1) Analyze the concept, target user, and main workflow. (2) Define the happy path, key edge cases, and the core screen inventory. (3) Outline the interactions, states, microcopy, and transitions needed for each screen. (4) Recommend the prototype build order and which screens should be fully interactive versus lightweight mocks. (5) Deliver a review-ready package with the prototype structure, rationale, and next iteration recommendations.`,heroOverlaySteps:[`Reviewing the concept, target user, and main flow`,`Mapping the core screens and edge-case states`,`Defining interactions, copy, and prototype build order`,`Prototype brief and review notes ready for the team`],generatingSteps:[`Reading {url} to understand the concept and intended user experience`,`Designing an agent to map screens, states, and interaction flow`,`Configuring the prototype build order and fidelity recommendations`,`Packaging the work into a prototype brief the team can review fast`],featureSectionTitle:`From raw idea to prototype-ready direction`,featureCardTitles:[`Connects to your design workflow`,`Outputs your team can review fast`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Figma, Docs, Notion, and ticketing tools stay connected so prototype decisions flow into the places your team already collaborates.`,`Screen map. Interaction notes. Microcopy suggestions. Build order. Computer turns a vague concept into a review-ready prototype package.`],capabilitySectionTitle:`Your prototype planner, on demand`,capabilitySectionSubtitle:`Share the idea, step away, and come back to a prototype brief with clear next steps.`,capabilityCards:[{title:`Concept Framing`,description:`Computer can absorb the product idea and user goal so the prototype reflects the right use case from the first pass.`},{title:`Screen Mapping`,description:`Computer can define the screen inventory, happy path, and edge cases so the prototype has the right structure before design work starts.`},{title:`Interaction Design`,description:`Computer can recommend states, transitions, and microcopy so the prototype communicates the intended experience clearly.`},{title:`Connect Your Tools`,description:`Computer can organize the prototype brief across Figma, Docs, and planning tools so the handoff into design work is straightforward.`},{title:`Feedback Loops`,description:`Computer can turn open questions into review prompts so stakeholders know what to react to first.`},{title:`Next Iteration`,description:`Computer can revisit the concept later and sharpen the prototype after team feedback or scope changes.`}]});export{t as default};
